const email = $('Select rows from a table1').item.json;
const newReply = $('AI Edit Draft').item.json.text;
const draft = $('Get Current Draft For Edit').item.json;

const currentRaw = draft.message?.raw;

if (!currentRaw) {
  throw new Error('Current Gmail draft raw MIME not found');
}

// Base64URL → MIME
let base64 = currentRaw
  .replace(/-/g, '+')
  .replace(/_/g, '/');

while (base64.length % 4) {
  base64 += '=';
}

let mime = Buffer.from(base64, 'base64').toString('utf8');

// Read top-level headers
const headerEnd = mime.search(/\r?\n\r?\n/);

if (headerEnd === -1) {
  throw new Error('Could not parse Gmail draft MIME');
}

const headers = mime.slice(0, headerEnd);
const unfoldedHeaders = headers.replace(/\r?\n[ \t]+/g, ' ');

// Check if draft is multipart/mixed
const mixedMatch = unfoldedHeaders.match(
  /Content-Type:\s*multipart\/mixed\b[^;\r\n]*;\s*boundary="?([^";\r\n]+)"?/i
);

if (mixedMatch) {
  // Draft contains attachments
  const boundary = mixedMatch[1];
  const delimiter = `--${boundary}`;

  const parts = mime.split(delimiter);

  let textPartUpdated = false;

  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];

    // Skip closing boundary
    if (part.trim().startsWith('--')) {
      continue;
    }

    const separatorMatch = part.match(/\r?\n\r?\n/);

    if (!separatorMatch) {
      continue;
    }

    const separatorIndex = separatorMatch.index;
    const separator = separatorMatch[0];

    let partHeaders = part.slice(0, separatorIndex);

    if (/Content-Type:\s*text\/plain\b/i.test(partHeaders)) {
      // Make sure body is treated as plain UTF-8 text
      if (/Content-Transfer-Encoding:/i.test(partHeaders)) {
        partHeaders = partHeaders.replace(
          /Content-Transfer-Encoding:[^\r\n]*/i,
          'Content-Transfer-Encoding: 8bit'
        );
      }

      parts[i] =
        partHeaders +
        separator +
        newReply +
        '\r\n';

      textPartUpdated = true;
      break;
    }
  }

  if (!textPartUpdated) {
    throw new Error('Could not find text/plain body in multipart Gmail draft');
  }

  mime = parts.join(delimiter);

} else {
  // Draft has no attachments
  // Preserve existing headers and replace only the message body
  const separatorMatch = mime.match(/\r?\n\r?\n/);

  if (!separatorMatch) {
    throw new Error('Could not find Gmail draft body');
  }

  const separatorIndex = separatorMatch.index;
  const separator = separatorMatch[0];

  let currentHeaders = mime.slice(0, separatorIndex);

  if (/Content-Transfer-Encoding:/i.test(currentHeaders)) {
    currentHeaders = currentHeaders.replace(
      /Content-Transfer-Encoding:[^\r\n]*/i,
      'Content-Transfer-Encoding: 8bit'
    );
  }

  mime =
    currentHeaders +
    separator +
    newReply;
}

// MIME → Base64URL
const raw = Buffer.from(mime, 'utf8')
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return [{
  json: {
    ...email,
    new_reply: newReply,
    raw
  }
}];

const email = $('Select rows from a table3').item.json;
const draft = $('Get Current Gmail Draft').item.json;
const input = $input.item;

const binary = input.binary?.attachment_0;

if (!binary) {
  throw new Error('Attachment binary not found');
}

const fileBuffer = await this.helpers.getBinaryDataBuffer(
  0,
  'attachment_0'
);

const fileName =
  input.json.fileName ||
  binary.fileName ||
  'attachment';

const mimeType =
  input.json.mimeType ||
  binary.mimeType ||
  'application/octet-stream';

const safeFileName = fileName.replace(/[\r\n"]/g, '_');

function decodeBase64Url(value) {
  value = value.replace(/-/g, '+').replace(/_/g, '/');

  while (value.length % 4) {
    value += '=';
  }

  return Buffer.from(value, 'base64').toString('utf8');
}

function encodeBase64Url(value) {
  return Buffer.from(value)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function wrapBase64(buffer) {
  const base64 = buffer.toString('base64');
  return base64.match(/.{1,76}/g)?.join('\r\n') || '';
}

const currentRaw = draft.message?.raw;

if (!currentRaw) {
  throw new Error('Current Gmail draft raw MIME not found');
}

const currentMime = decodeBase64Url(currentRaw);

const headerEnd = currentMime.search(/\r?\n\r?\n/);

if (headerEnd === -1) {
  throw new Error('Could not parse current Gmail MIME');
}

const headers = currentMime.slice(0, headerEnd);
const unfoldedHeaders = headers.replace(/\r?\n[ \t]+/g, ' ');

const mixedMatch = unfoldedHeaders.match(
  /Content-Type:\s*multipart\/mixed\b[^;\r\n]*;\s*boundary="?([^";\r\n]+)"?/i
);

let finalMime;

if (mixedMatch) {
  const boundary = mixedMatch[1];
  const closingBoundary = `--${boundary}--`;

  const closingIndex = currentMime.lastIndexOf(closingBoundary);

  if (closingIndex === -1) {
    throw new Error('Multipart closing boundary not found');
  }

  const newAttachmentPart =
    `--${boundary}\r\n` +
    `Content-Type: ${mimeType}; name="${safeFileName}"\r\n` +
    `Content-Disposition: attachment; filename="${safeFileName}"\r\n` +
    `Content-Transfer-Encoding: base64\r\n` +
    `\r\n` +
    `${wrapBase64(fileBuffer)}\r\n`;

  finalMime =
    currentMime.slice(0, closingIndex) +
    newAttachmentPart +
    currentMime.slice(closingIndex);

} else {
  const boundary = `n8n_${Date.now()}`;

  finalMime =
    `To: ${email.sender}\r\n` +
    `Subject: Re: ${email.subject}\r\n` +
    `MIME-Version: 1.0\r\n` +
    `Content-Type: multipart/mixed; boundary="${boundary}"\r\n` +
    `\r\n` +

    `--${boundary}\r\n` +
    `Content-Type: text/plain; charset="UTF-8"\r\n` +
    `Content-Transfer-Encoding: 8bit\r\n` +
    `\r\n` +
    `${email.draft_reply || ''}\r\n` +

    `--${boundary}\r\n` +
    `Content-Type: ${mimeType}; name="${safeFileName}"\r\n` +
    `Content-Disposition: attachment; filename="${safeFileName}"\r\n` +
    `Content-Transfer-Encoding: base64\r\n` +
    `\r\n` +
    `${wrapBase64(fileBuffer)}\r\n` +

    `--${boundary}--`;
}

const raw = encodeBase64Url(finalMime);

return {
  json: {
    message_id: email.message_id,
    draft_id: email.draft_id,
    thread_id: email.thread_id,
    fileName,
    mimeType,
    raw,
  },
};

