const item = $input.item;

const fileName = $('Edit Fields').item.json.document_name || 'attachment';
const mimeType = $('Edit Fields').item.json.document_mime_type || 'application/octet-stream';

return [{
  json: {
    ...item.json,
    fileName,
    mimeType,
  },
  binary: {
    attachment_0: {
      ...item.binary.data,
      fileName,
      mimeType,
    },
  },
}];

const draft = $('Get Updated Gmail Draft').item.json;

const raw = draft.message?.raw;

if (!raw) {
  throw new Error('Gmail draft raw message not found');
}

// Base64URL → MIME text
let base64 = raw
  .replace(/-/g, '+')
  .replace(/_/g, '/');

while (base64.length % 4) {
  base64 += '=';
}

const mime = Buffer.from(base64, 'base64').toString('utf8');

// Extract attachment filenames
const fileNames = [];

const regex =
  /Content-Disposition:\s*attachment[\s\S]*?filename\s*=\s*(?:"([^"]+)"|([^\r\n;]+))/gi;

let match;

while ((match = regex.exec(mime)) !== null) {
  const name = (match[1] || match[2] || '').trim();

  if (name && !fileNames.includes(name)) {
    fileNames.push(name);
  }
}

return [{
  json: {
    attachment_names: fileNames,
    attachment_count: fileNames.length,
    attachments_text: fileNames.length
      ? fileNames.map((name, i) => `${i + 1}. ${name}`).join('\n')
      : 'No attachments'
  }
}];

